        // Funcoes para resolver as chaves estrangeiras automaticamente e evitar duplicatas
        $resolveUnidade = function($name) {
            if (!$name) return null;
            static $cache = [];
            if (isset($cache[$name])) return $cache[$name];
            $id = DB::table('unidades')->where('nome', $name)->value('id');
            if (!$id) $id = DB::table('unidades')->insertGetId(['nome' => $name]);
            return $cache[$name] = $id;
        };

        $resolveCurso = function($name) {
            if (!$name) return null;
