            if (isset($cache[$name])) return $cache[$name];
            $id = DB::table('cursos')->where('nome', $name)->value('id');
            if (!$id) $id = DB::table('cursos')->insertGetId(['nome' => $name]);
            return $cache[$name] = $id;
        };

